typedef unsigned char uint8;
typedef unsigned int uint32;
typedef float rational_t;

class color32 {
public:
    union { struct { uint8 b, g, r, a; } c; uint32 i; };
    color32(uint32 value = 0) : i(value) {}
    uint8 get_alpha() const { return c.a; }
    void set_alpha(uint8 value) { c.a = value; }
};

struct string_buf {
    unsigned long long *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;
};

class stringx {
protected:
    char *chars;
    string_buf *my_buf;
public:
    stringx();
    stringx(const stringx &);
    ~stringx();
    stringx &operator=(const stringx &);
    int length() const;
    int find(int pos, char c) const;
    stringx read_token(char *delim, int start_index = 0, bool ignore_leading = true, bool chop = false);
};

class Font {
public:
    enum HORIZJUST { HORIZJUST_LEFT, HORIZJUST_CENTER, HORIZJUST_RIGHT };
    enum VERTJUST { VERTJUST_TOP, VERTJUST_CENTER, VERTJUST_BOTTOM };
    bool unset;
    int max_width;
    void render(const stringx &text, color32 color, bool no_color, bool override_alpha,
                rational_t x, rational_t y, rational_t depth,
                HORIZJUST horizJustification, VERTJUST vertJustification,
                bool even_number_spacing, rational_t scale = 1.0f,
                float art_button_scale = -1.0f, float *delta_x = 0,
                float *delta_y = 0, rational_t angle = 0.0f,
                bool random_string_fade = true);
};

inline int FTOI(float input) {
    register float output;
    __asm__ volatile("cvt.w.s %0, %1" : "=f"(output) : "f"(input));
    return (int &)output;
}

class TextString {
protected:
    Font *font;
    stringx text;
    float x;
    float y;
    int z;
    Font::HORIZJUST hJustify;
    Font::VERTJUST vJustify;
    bool even_number_spacing;
    int fade;
    float fade_alpha;
    float fade_timer;
    float scale;
    float button_scale;
    bool override_alpha;
public:
    bool checkTime;
    float time;
    bool no_color;
    color32 color;
    virtual void Render(stringx *t, float x1, float y1);
};

class MultiLineString : public TextString {
protected:
    int vSpacing;
    int line_num;
    static const int max_fonts = 20;
    Font *fonts[max_fonts];
protected:
    virtual void Render(stringx *t, float x1, float y1);
};

void MultiLineString::Render(stringx* t, float x1, float y1)
{
	stringx token;
	int current_index = 0;
	int num_lines = 1;
	int line_shift = 0;   // the amount to shift to compensate for vertical justification in multi-line text
	int current_line = 0; // which line we're currently rendering
	color32 tmp_color = color;

	if(fade != 0) tmp_color.set_alpha(FTOI(fade_alpha*255.0f));
	if(tmp_color.get_alpha() > color.get_alpha()) tmp_color = color;

	if(!font->unset)
	{
		// First figure out how many different lines there are
		while((current_index = t->find(current_index, '\n')) != -1)
		{
			num_lines++;
			current_index++;
		}

		// Now figure out how much to shift the text vertically.
		switch(vJustify)
		{
		case Font::VERTJUST_TOP:
			// If vJustify is VERTJUST_TOP then don't shift.
			line_shift = 0; break;
		case Font::VERTJUST_CENTER:
			// If vJustify is VERTJUST_CENTER then shift up by half per extra line.
			line_shift = (vSpacing / 2) * (num_lines - 1); break;
		case Font::VERTJUST_BOTTOM:
			// If vJustify is VERTJUST_BOTTOM then shift up one per extra line.
			line_shift = vSpacing * (num_lines - 1); break;
		}

		// Now print out the lines one at a time
		current_index = 0;
		current_line = 0;
		do
		{
			token = t->read_token("\n", current_index);
			current_index += token.length() + 1;
			Font* f = font;
			if(fonts[current_line] != NULL && !fonts[current_line]->unset)
				f = fonts[current_line];
			f->render(token, tmp_color, no_color, override_alpha, x1, y1 - line_shift + current_line * vSpacing,
			             z, hJustify, vJustify, even_number_spacing, scale, button_scale);
			current_line++;
		} while(current_line < num_lines);
	}
}
